package com.bank.payroll;

import java.util.*;
import java.util.logging.*;

public class FlattenDemo {
    private static final Logger log = Logger.getLogger("Flatten");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        Department trading = new Department("Trading", List.of(
            new Employee(1L, "Rajesh"), new Employee(4L, "Sneha")));
        Department risk = new Department("Risk", List.of(
            new Employee(2L, "Priya"), new Employee(6L, "Neha")));
        List<Department> depts = List.of(trading, risk);

        DepartmentService service = new DepartmentService();
        List<Employee> all = service.allEmployees(depts);

        log.info(() -> "Total employees across all departments: " + all.size());
        all.forEach(e -> log.info(() -> "  " + e.getName()));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
        Employee(Long id, String name) { this.id = id;
        this.name = name; }
    String getName() { return name; }
}

// ─── Would be in model/Department.java ───
class Department {
    private final String name;
    private final List<Employee> employees;
        Department(String name, List<Employee> employees) { this.name = name;
        this.employees = employees; }
    List<Employee> getEmployees() { return employees; }
    String getName() { return name; }
}

// ─── Would be in service/DepartmentService.java ───
class DepartmentService {
    // flatMap turns Stream<Department> into a single Stream<Employee>
    List<Employee> allEmployees(List<Department> departments) {
        return departments.stream()
            .flatMap(d -> d.getEmployees().stream())   // flatten one level of nesting
            .collect(java.util.stream.Collectors.toList());
    }
}
